import React, { useEffect, useState } from "react";

function SavedPage({ token }) {
  const [saved, setSaved] = useState([]);

  useEffect(() => {
    if (!token) return;
    fetch("http://127.0.0.1:8000/api/saved/", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => res.json())
      .then((data) => setSaved(data))
      .catch(console.error);
  }, [token]);

  if (!token) return <p>Увійдіть, щоб переглянути збережене.</p>;

  if (saved.length === 0) return <p>Немає збережених статей.</p>;

  return (
    <div className="saved-container">
      <h2>📚 Збережені статті</h2>
      {saved.map((s) => {
        const a = s.article_detail; // беремо повні дані статті
        return (
          <div key={s.id} className="saved-article">
            <h3>{a.title}</h3>
            <p>{a.content}</p>

            {a.image && (
              <img src={a.image} alt={a.title} style={{ maxWidth: "100%" }} />
            )}

            {a.video && (
              <video controls style={{ maxWidth: "100%" }}>
                <source src={a.video} type="video/mp4" />
                Ваш браузер не підтримує відео.
              </video>
            )}

            {a.comments && a.comments.length > 0 && (
              <div className="comments">
                <h4>Коментарі:</h4>
                <ul>
                  {a.comments.map((c) => (
                    <li key={c.id}>
                      <b>{c.author}:</b> {c.text}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

export default SavedPage;
